import { cleanText, connKey, isIpv4, normalizeHost } from "@/lib/server-directory";

/**
 * Steam master-server list -> directory candidates. PURE parsing + a thin
 * fetcher; the database half is lib/directory-ingest/run.ts.
 *
 * Source: Steam Web API `IGameServersService/GetServerList` (needs a free Steam
 * Web API key in STEAM_WEB_API_KEY). Using it for a public directory is an
 * interpretation of Valve's terms (https://steamcommunity.com/dev/apiterms), not an
 * explicit grant, so nothing here runs unless an admin turned ingestion on and the
 * legal gates in lib/directory-steam.ts passed. The fetcher is only ever called by
 * the worker sweep (lib/directory-ingest/sweep.ts) and scripts/directory-ingest.ts,
 * never from a page render, and it makes exactly ONE request per game per call.
 * The same key is shared with the Workshop catalog sync (lib/modsync); the Valve
 * limit of 100,000 calls/day is per key, so the sweep keeps its own far lower cap.
 *
 * Response rows (the documented fields we use): addr "ip:queryPort",
 * gameport, name, appid, gamedir, version, region, players, max_players, bots,
 * map, secure, dedicated, os, gametype (comma-separated tags). Anything else
 * is ignored; anything missing stays empty — nothing is invented.
 */

/** Families that register on the Steam master list, with their Steam app ids. */
export const VALVE_APPIDS: Record<string, number> = {
  valheim: 892970,
  projectzomboid: 108600,
  rust: 252490,
  cs2: 730,
  tf2: 440,
  gmod: 4000,
  l4d2: 550,
  ark: 346110,
  unturned: 304930,
  sdtd: 251570,
  conan: 440900,
};

/**
 * More families whose dedicated servers register on the Steam master list. These app ids are from Valve's public
 * store and are NOT in the sweep until an admin lists the family in Setting `directory_steam_extra_games`
 * (comma separated), because each one needs an owner-approved one-off sample call first: if the list answers
 * with no rows (or only another game), the family belongs in the "no public source" bucket and stays off.
 * UNVERIFIED against the live API in this branch (no key available to the build agent): see docs/DIRECTORY-SOURCES.md.
 */
export const STEAM_EXTRA_APPIDS: Record<string, number> = {
  cs16: 10, dayz: 221100, arma3: 107410, squad: 393380, mordhau: 629760, kf2: 232090, sandstorm: 581320,
  barotrauma: 602960, spaceengineers: 244850, empyrion: 383120, stationeers: 544550, theforest: 242760,
  sonsoftheforest: 1326470, vrising: 1604030, abioticfactor: 427410, soulmask: 2646460, theisle: 376210,
  enshrouded: 1203620, icarus: 1149460,
};
export const ALL_STEAM_APPIDS: Record<string, number> = { ...STEAM_EXTRA_APPIDS, ...VALVE_APPIDS };

/** Families the sweep refreshes: the proven base set plus the extras an admin enabled (unknown names are ignored). */
export function sweepGames(extraCsv: string): string[] {
  const extra = extraCsv.split(",").map((g) => g.trim().toLowerCase()).filter((g) => STEAM_EXTRA_APPIDS[g] && !VALVE_APPIDS[g]);
  return [...Object.keys(VALVE_APPIDS), ...new Set(extra)];
}

export type ValveRaw = {
  addr?: string; gameport?: number; name?: string; appid?: number; version?: string;
  players?: number; max_players?: number; bots?: number; map?: string; dedicated?: boolean; gametype?: string;
};

export type ExternalCandidate = {
  source: "valve";
  sourceKey: string;
  game: string;
  name: string;
  host: string;
  ip: string;
  port: number;
  queryPort: number | null;
  map: string | null;
  players: number | null;
  maxPlayers: number | null;
  version: string | null;
  tags: string[];
  connKey: string;
  ipKey: string;
};

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.floor(v) : null);

/** Server names come from strangers: strip controls, collapse space, bound length, drop empties/links-only. */
export function cleanServerName(raw: unknown): string | null {
  const t = cleanText(raw, 80);
  if (!t || t.length < 3) return null;
  if (!/[\p{L}\p{N}]/u.test(t)) return null;
  return t;
}

export function parseValveRow(game: string, r: ValveRaw): ExternalCandidate | null {
  const m = /^(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})$/.exec(String(r.addr ?? ""));
  if (!m) return null;
  const ip = normalizeHost(m[1]);
  if (!isIpv4(ip) || /^(0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(ip)) return null;
  const queryPort = Number(m[2]);
  // The join port is `gameport` when the row reports one; otherwise the address port.
  const port = num(r.gameport) && num(r.gameport)! > 0 && num(r.gameport)! < 65536 ? num(r.gameport)! : queryPort;
  if (!(port >= 1 && port <= 65535)) return null;
  const name = cleanServerName(r.name);
  if (!name) return null;
  if (r.dedicated === false) return null;
  const tags = String(r.gametype ?? "").split(",").map((t) => cleanText(t, 24)).filter((t): t is string => !!t).slice(0, 8);
  const key = connKey(game, ip, port);
  return {
    source: "valve", sourceKey: `${ip}:${port}`, game, name, host: ip, ip, port,
    queryPort: queryPort !== port ? queryPort : null,
    map: cleanText(r.map, 40), players: num(r.players), maxPlayers: num(r.max_players),
    version: cleanText(r.version, 24), tags, connKey: key, ipKey: key,
  };
}

export function parseValveResponse(game: string, json: unknown): ExternalCandidate[] {
  const rows = (json as { response?: { servers?: ValveRaw[] } } | null)?.response?.servers;
  if (!Array.isArray(rows)) return [];
  const seen = new Set<string>();
  const out: ExternalCandidate[] = [];
  for (const r of rows) {
    const c = parseValveRow(game, r);
    if (!c || seen.has(c.sourceKey)) continue;
    seen.add(c.sourceKey);
    out.push(c);
  }
  return out;
}

/** `status` = the HTTP status when Steam answered one; `retryAfterSec` = its Retry-After header when sent. */
export class ValveFetchError extends Error {
  constructor(message: string, readonly status?: number, readonly retryAfterSec?: number) { super(message); }
}

/** One bounded request. Throws ValveFetchError on anything but a clean 200 JSON body. */
export async function fetchValveList(game: string, opts: { key: string; limit?: number; timeoutMs?: number; fetchImpl?: typeof fetch }): Promise<ExternalCandidate[]> {
  const appid = ALL_STEAM_APPIDS[game];
  if (!appid) throw new ValveFetchError(`No Steam app id known for ${game}`);
  const limit = Math.min(Math.max(opts.limit ?? 1000, 1), 5000);
  // dedicated + at least one open slot is not required; empty servers are useful listings too.
  const filter = `\\appid\\${appid}\\dedicated\\1`;
  const url = `https://api.steampowered.com/IGameServersService/GetServerList/v1/?key=${encodeURIComponent(opts.key)}&limit=${limit}&filter=${encodeURIComponent(filter)}`;
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), opts.timeoutMs ?? 25_000);
  try {
    const res = await (opts.fetchImpl ?? fetch)(url, { signal: ctl.signal, headers: { accept: "application/json" } });
    if (!res.ok) {
      const ra = Number(res.headers?.get?.("retry-after"));
      throw new ValveFetchError(`Steam list answered HTTP ${res.status}`, res.status, Number.isFinite(ra) && ra > 0 ? ra : undefined);
    }
    return parseValveResponse(game, await res.json());
  } catch (e) {
    if (e instanceof ValveFetchError) throw e;
    // never echo the URL (it carries the API key)
    throw new ValveFetchError(e instanceof Error && e.name === "AbortError" ? "Steam list timed out" : "Steam list request failed");
  } finally {
    clearTimeout(t);
  }
}
import { db } from "@/lib/db";
import { getSetting, setSetting } from "@/lib/settings";
import { ingestValveGame, type IngestResult } from "./run";
import type { ReverseFn } from "./ptr";
import { sweepGames, ValveFetchError } from "./valve";
import { loadSteamConfig } from "./gates";
import {
  backoffMs, breakerDecision, callsRemaining, dayKey, dueGames, sweepGate, type SweepSkip,
} from "./schedule";

/**
 * The Steam list sweep: what the worker runs every few minutes (worker/directory.ts). Each tick decides,
 * in a pinned order (schedule.ts sweepGate), whether it may run at all; then refreshes at most
 * MAX_GAMES_PER_TICK games that are due, ONE Steam request each, counting every request against the daily cap.
 * A failure backs off exponentially and stops the tick; repeated failures open the breaker; a 401/403
 * opens it AND switches the sweep off. All state is in DirectorySource("steam"), so restarts resume.
 */
export const STEAM_SOURCE = "steam";
const CLAIM_MS = 10 * 60_000;
export const SWEEP_LIMIT = 1000;

export type SweepGameResult = { game: string; ok: boolean; error?: string; result?: IngestResult };
export type SweepReport = { skipped?: SweepSkip; games: SweepGameResult[]; disabled?: boolean };

export async function ensureSource(key: string) {
  return db.directorySource.upsert({ where: { key }, create: { key }, update: {} });
}

/** Strip anything that could be the API key from a message headed for the database. */
export function redactKey(msg: string, key: string | undefined): string {
  let m = msg;
  if (key) m = m.split(key).join("[key]");
  return m.replace(/key=[A-Za-z0-9]+/g, "key=[key]").slice(0, 300);
}

export async function directorySweepTick(opts: {
  now?: number; key?: string; fetchImpl?: typeof fetch; ingest?: typeof ingestValveGame; envKill?: boolean; reverse?: ReverseFn;
} = {}): Promise<SweepReport> {
  const now = opts.now ?? Date.now();
  const key = opts.key ?? process.env.STEAM_WEB_API_KEY;
  const ingest = opts.ingest ?? ingestValveGame;
  const cfg = await loadSteamConfig();
  const src = await ensureSource(STEAM_SOURCE);
  const skip = sweepGate({
    envKill: opts.envKill ?? process.env.DIRECTORY_SWEEP_DISABLED === "1",
    ingestOn: cfg.ingestOn, sweepOn: cfg.sweepOn, legalProblems: cfg.legalProblems, hasKey: !!key,
    circuitOpenUntil: src.circuitOpenUntil, nextAttemptAt: src.nextAttemptAt, runningUntil: src.runningUntil,
    remainingCalls: callsRemaining(src, now), now,
  });
  if (skip) {
    if (skip === "no-key") {
      await db.directorySource.update({ where: { key: STEAM_SOURCE }, data: { lastError: "Needs STEAM_WEB_API_KEY in the worker's environment.", lastErrorAt: new Date(now), nextAttemptAt: new Date(now + 3600_000) } });
    }
    return { skipped: skip, games: [] };
  }
  // Claim: two worker processes must never sweep at once.
  const claimed = await db.directorySource.updateMany({
    where: { key: STEAM_SOURCE, OR: [{ runningUntil: null }, { runningUntil: { lt: new Date(now) } }] },
    data: { runningUntil: new Date(now + CLAIM_MS) },
  });
  if (!claimed.count) return { skipped: "running", games: [] };

  const force = src.runRequested;
  const report: SweepReport = { games: [] };
  let callsDay = src.callsDay, callsToday = src.callsDay === dayKey(now) ? src.callsToday : 0;
  let errors = src.consecutiveErrors, lastOkAt = src.lastOkAt, lastError = src.lastError, lastErrorAt = src.lastErrorAt;
  let circuit: Date | null = null, next: Date | null = null;
  try {
    const rows = await db.directoryIngestRun.groupBy({
      by: ["game"], where: { source: "valve", status: { in: ["ok", "suspicious"] }, finishedAt: { not: null } }, _max: { finishedAt: true },
    });
    const last = new Map(rows.map((r) => [r.game, r._max.finishedAt]));
    const due = dueGames(sweepGames(await getSetting("directory_steam_extra_games", "")), last, now, { baseMin: cfg.intervalMin, force });
    if (!due.length) report.skipped = "nothing-due";
    for (const game of due) {
      if (callsRemaining({ callsDay, callsToday }, now) <= 0) { report.skipped = "budget"; break; }
      callsDay = dayKey(now); callsToday += 1; // counted BEFORE the call: a failed request still spent budget
      try {
        const result = await ingest(game, { apply: true, key: key!, limit: SWEEP_LIMIT, fetchImpl: opts.fetchImpl, reverse: opts.reverse, trigger: force ? "admin" : "worker" });
        report.games.push({ game, ok: true, result });
        errors = 0; lastOkAt = new Date(now); lastError = null; lastErrorAt = null; circuit = null; next = null;
      } catch (e) {
        const status = e instanceof ValveFetchError ? e.status : undefined;
        const msg = redactKey(e instanceof Error ? e.message : "sweep failed", key);
        errors += 1; lastError = `${game}: ${msg}`; lastErrorAt = new Date(now);
        const b = breakerDecision(errors, status);
        next = new Date(now + backoffMs(errors, e instanceof ValveFetchError ? e.retryAfterSec : undefined));
        if (b.open) circuit = new Date(now + b.openMs);
        if (b.disable) {
          await setSetting("directory_sweep_enabled", "false");
          report.disabled = true;
          console.error(`[directory] Steam answered HTTP ${status}: sweep switched OFF. Check the key and Valve's terms before turning it back on.`);
        }
        report.games.push({ game, ok: false, error: msg });
        break; // never hammer the next game after a failure
      }
    }
  } finally {
    await db.directorySource.update({
      where: { key: STEAM_SOURCE },
      data: {
        runningUntil: null, runRequested: false, lastRunAt: new Date(now), lastOkAt, lastError, lastErrorAt,
        consecutiveErrors: errors, circuitOpenUntil: circuit ?? (errors === 0 ? null : src.circuitOpenUntil),
        nextAttemptAt: next, callsDay, callsToday,
        stats: { games: report.games.map((g) => ({ game: g.game, ok: g.ok, fetched: g.result?.fetched ?? null })), skipped: report.skipped ?? null },
      },
    });
  }
  return report;
}
/**
 * Directory source adapters (v2). A provider turns ONE public, permitted source into `ProviderCandidate`s;
 * everything shared (gates, rate limit, breaker, dedupe, blocklist, upsert, prune, liveness) is in
 * lib/directory-ingest/provider-run.ts and is the same for every source. Steam keeps its own proven path
 * (valve.ts / run.ts / sweep.ts) and is described in the registry only for attribution and docs.
 *
 * Every provider is default OFF (Setting `directory_src_<key>_enabled`) and, like Steam, cannot run until
 * somebody has recorded that they read the source's terms (`directory_src_<key>_reviewed_by`).
 */

/** How a row's liveness is checked. `listing` = the source's own heartbeat list is the evidence (no packets from us). */
export type ProbeKind = "a2s" | "slp" | "raknet" | "listing";

export type ProviderCandidate = {
  sourceKey: string;
  game: string;
  name: string;
  host: string;
  ip: string | null;
  port: number;
  queryPort: number | null;
  map: string | null;
  players: number | null;
  maxPlayers: number | null;
  version: string | null;
  tags: string[];
  country: string | null;
  connKey: string;
  ipKey: string | null;
  /** The source itself says this server is up right now (listing providers). null = unknown, probe decides. */
  alive: boolean | null;
};

export type ProviderAttribution = {
  /** Stored on ExternalServer.attribution and used to pick the footer block. */
  key: string;
  /** Plain sentence shown on every page that lists rows from this source (never claims endorsement). */
  text: string;
  url: string;
  linkLabel: string;
};

export type FetchContext = {
  fetchImpl?: typeof fetch;
  /** ETag from the previous successful run, sent as If-None-Match. */
  etag?: string | null;
};

export type FetchResult = { candidates: ProviderCandidate[]; notModified?: boolean; etag?: string | null; requests: number };

export type DirectoryProvider = {
  key: string;
  label: string;
  games: readonly string[];
  /** Minutes between refreshes (the source's own caching and politeness decide this, not our appetite). */
  intervalMin: number;
  /** Rows not listed by the source for this many days are removed. */
  pruneAfterDays: number;
  termsUrl: string;
  attribution: ProviderAttribution;
  /** Hard ceiling on our requests per UTC day to this source. */
  dailyCallCap: number;
  fetch(ctx: FetchContext): Promise<FetchResult>;
  probeKindFor(game: string): ProbeKind | null;
};

export class ProviderFetchError extends Error {
  constructor(message: string, readonly status?: number, readonly retryAfterSec?: number) { super(message); }
}

export const enableSettingFor = (key: string) => `directory_src_${key}_enabled`;
export const reviewedSettingFor = (key: string) => `directory_src_${key}_reviewed_by`;
