/** Every non-Steam adapter. Adding a source = one file in this folder + one line here + a row in docs/DIRECTORY-SOURCES.md. */
export const PROVIDERS: readonly DirectoryProvider[] = [vintageStoryProvider, truckersMpProvider];

export const providerByKey = (key: string): DirectoryProvider | undefined => PROVIDERS.find((p) => p.key === key);

/** Attribution for any `ExternalServer.attribution` value (Steam's own block is richer: see steamAttributionHtml). */
export function attributionFor(key: string | null | undefined): ProviderAttribution | null {
  return attributionForKey(key) ?? providerByKey(key ?? "")?.attribution ?? null;
}

/** Liveness protocol per family (see probe-kind.ts). */
export { probeKindForGame } from "./probe-kind";

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/** Footer block for a non-Steam source: its sentence plus a normal followed link to the source's site. */
export function providerAttributionHtml(key: string): string {
  const a = attributionFor(key);
  if (!a || key === "steam") return "";
  return `<aside class="dr-attrib" aria-label="${esc(a.linkLabel)} attribution" data-attrib="${esc(a.key)}"><p>${esc(a.text)} <a href="${esc(a.url)}" rel="noopener">${esc(a.linkLabel)}</a></p></aside>`;
}
