/**
 * TruckersMP official API (https://api.truckersmp.com/v2/servers): documented, public, no key. robots.txt asks
 * for a 2 second crawl delay (we make ONE request per 10 minutes). It lists TruckersMP's own multiplayer
 * servers for Euro Truck Simulator 2 and American Truck Simulator, not community servers, so the directory labels
 * them "official TruckersMP servers". Their terms page could not be fetched (HTTP 403) on 2026-10-04, so the
 * source stays default OFF until a person records they read them.
 *
 * Verified live 2026-10-04: 200 JSON `{response:[{id, game:"ETS2"|"ATS", ip, port, name, shortname, online,
 * players, queue, maxplayers, promods ...}]}`. `online` is the source's own liveness statement.
 */
export const TRUCKERSMP_URL = "https://api.truckersmp.com/v2/servers";

export type TmpRaw = { id?: unknown; game?: unknown; ip?: unknown; port?: unknown; name?: unknown; shortname?: unknown; online?: unknown; players?: unknown; maxplayers?: unknown; promods?: unknown };

const int = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) && v >= 0 && v < 1_000_000 ? Math.floor(v) : null);

export function parseTmpRow(r: TmpRaw): ProviderCandidate | null {
  const g = String(r.game ?? "").toUpperCase();
  const game = g === "ETS2" ? "ets2" : g === "ATS" ? "ats" : null;
  if (!game) return null;
  const host = normalizeHost(String(r.ip ?? ""));
  const port = int(r.port);
  if (!isIpv4(host) || !isPublicIpv4(host) || !port || port > 65535) return null;
  const name = cleanText(r.name, 80);
  if (!name) return null;
  const max = int(r.maxplayers), players = int(r.players);
  const key = connKey(game, host, port);
  return {
    sourceKey: `${host}:${port}:${int(r.id) ?? 0}`, game, name: `TruckersMP ${name}`.slice(0, 80), host, ip: host, port, queryPort: null, map: null,
    players: max !== null && players !== null && players > max ? null : players, maxPlayers: max, version: null,
    tags: ["official", ...(r.promods === true ? ["promods"] : [])], country: null, connKey: key, ipKey: key,
    alive: r.online === true,
  };
}

export function parseTmpResponse(json: unknown): ProviderCandidate[] {
  const rows = (json as { response?: TmpRaw[] } | null)?.response;
  if (!Array.isArray(rows)) return [];
  const seen = new Set<string>();
  const out: ProviderCandidate[] = [];
  for (const r of rows) {
    const c = parseTmpRow(r);
    if (!c || seen.has(c.sourceKey)) continue;
    seen.add(c.sourceKey);
    out.push(c);
  }
  return out;
}

export const truckersMpProvider: DirectoryProvider = {
  key: "truckersmp", label: "TruckersMP official servers", games: ["ets2", "ats"],
  intervalMin: 10, pruneAfterDays: 1, dailyCallCap: 200,
  termsUrl: "https://truckersmp.com/terms",
  attribution: TRUCKERSMP_ATTRIBUTION,
  probeKindFor: () => "listing",
  async fetch(ctx: FetchContext): Promise<FetchResult> {
    const r = await politeGetJson(TRUCKERSMP_URL, { fetchImpl: ctx.fetchImpl, etag: ctx.etag, timeoutMs: 20_000 });
    if (r.notModified) return { candidates: [], notModified: true, etag: r.etag, requests: 1 };
    return { candidates: parseTmpResponse(r.json), etag: r.etag, requests: 1 };
  },
};
