  if (e.checkedAt) return `<time class="dr-chk" datetime="${new Date(e.checkedAt).toISOString()}" data-kind="Checked">Checked ${utcStamp(e.checkedAt)}</time>`;
  if (e.attribution && e.seenAt) return `<time class="dr-chk" datetime="${new Date(e.seenAt).toISOString()}" data-kind="Seen on the list">Seen on the list ${utcStamp(e.seenAt)}</time>`;
  return "";
}

/** The Valve/Steam attribution block, only when some listed server's data came from the Steam list. */
export function attributionFor(list: DirEntry[]): string {
  const steam = list.some((e) => e.attribution === "steam") ? steamAttributionHtml({ logo: steamLogoPresent() }) : "";
  const others = [...new Set(list.map((e) => e.attribution).filter((k): k is string => !!k && k !== "steam"))]
    .map((k) => providerAttributionHtml(k)).join("");
  return steam + others;
}

const filterTokens = (e: DirEntry, mode?: string) =>
  [e.nxeon ? "nx" : "ext", e.imageUrl ? "img" : "", mode ?? ""].filter(Boolean).join(" ");

/** One listing card (exported for visual checks with sample rows). */
export function card(e: DirEntry, opts: { mode?: string } = {}) {
  const art = gameArt(e.game).cover;
  const q = [e.name, e.tagline, e.description, gameName(e.game), e.address].join(" ").toLowerCase();
  const badge = e.nxeon
    ? `<span class="dr-badge nx" title="Hosted on Nxeon">${I("shield")}Nxeon</span>`
    : `<span class="dr-badge x" title="Found on a public server list">Public list</span>`;
  const fresh = freshnessHtml(e);
  const meta = [
    e.players != null ? `${e.players}${e.maxPlayers ? ` / ${e.maxPlayers}` : ""} playing` : e.maxPlayers ? `Up to ${e.maxPlayers} players` : "",
    e.region ?? "", e.country ?? "",
  ].filter(Boolean);
  const head = e.imageUrl
    ? `<div class="dr-banner"><img src="${esc(e.imageUrl)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" width="640" height="320"></div>`
    : "";
  const site = e.websiteUrl ? `<a class="dr-go" href="${esc(e.websiteUrl)}" rel="ugc nofollow noopener noreferrer" target="_blank">Website <span aria-hidden="true">↗</span></a>` : "";
  return `<article class="au-card dr-card${e.imageUrl ? " has-img" : ""}" data-q="${esc(q)}" data-f="${esc(filterTokens(e, opts.mode))}">`
    + head
    + `<div class="dr-top">${art ? `<img class="dr-ic" src="${esc(art)}" alt="" width="46" height="62" loading="lazy">` : ""}<div><h3 title="${esc(e.name)}">${esc(e.name)}</h3><span class="dr-mode">${esc(gameName(e.game))}</span></div>${badge}</div>`
    + (e.tagline ? `<p class="dr-tag">${esc(e.tagline)}</p>` : "")
    + (e.description ? `<p class="dr-desc">${esc(e.description)}</p>` : "")
    + (meta.length ? `<div class="dr-meta">${meta.map((m) => `<span>${esc(m)}</span>`).join("")}</div>` : "")
    + (fresh ? `<p class="dr-fresh">${fresh}</p>` : "")
    + `<div class="dr-addr"><code title="${esc(e.address)}">${esc(e.address)}</code><button type="button" class="dr-copy" data-copy="${esc(e.address)}">Copy</button></div>`
    + (e.href ? `<a class="dr-go" href="${esc(nxmHref(e.href))}">${e.source === "nxeon-community" ? "How to join" : "View server"} <span aria-hidden="true">→</span></a>` : "")
    + site
    + `</article>`;
}

function featuredSection(list: DirEntry[]): string {
