export async function meta(p: Record<string, string>) {
  if (p.view === "free") return { image: gameArt("minecraft").hero ?? undefined };
  if (p.view === "all") {
    return {
      title: "Public Game Server Directory",
      description: "Browse public game servers: Minecraft, Valheim, Project Zomboid and more. Servers hosted on Nxeon carry a badge. Pick a game, copy the address and connect.",
      image: gameArt("minecraft").hero ?? undefined,
    };
  }
  if (p.view !== "game") notFound();
  const game = String(p.game ?? "").toLowerCase();
  if (!isGameFamily(game)) notFound();
  const { entries } = await loadDirectory({ game });
  const name = gameName(game);
  return {
    title: `${name} Server List: Public ${name} Servers to Join`,
    description: entries.length
      ? `Public ${name} servers you can join now. ${entries.some((e) => e.nxeon) ? "Servers hosted on Nxeon carry a badge. " : ""}Copy an address and connect, or host your own.`
      : `The ${name} server directory. List your own ${name} server hosted on Nxeon for others to find.`,
    image: gameArt(game).hero ?? undefined,
    noindex: !indexableGamePage(entries),
  };
}
