/**
 * Direct Valve "Source query" liveness probe (A2S_INFO, with the challenge step Valve
 * added in 2020). PURE packet building/parsing + an injectable transport, so every
 * decision is unit-tested with fixture packets and nothing here needs a network.
 *
 * Spec: https://developer.valvesoftware.com/wiki/Server_queries
 *
 *   request   FF FF FF FF 54 "Source Engine Query" 00 [challenge:int32]
 *   challenge FF FF FF FF 41 <challenge:4 bytes>      -> resend the request with it appended
 *   info      FF FF FF FF 49 protocol, name\0, map\0, folder\0, game\0, appid:u16le, players,
 *             max, bots, type, environment, visibility, vac, [The Ship extras], version\0, EDF...
 *
 * PRIVACY / SCOPE (hard rules, mirrored by the tests):
 *  - Only A2S_INFO is ever sent. A2S_PLAYER (player names) and A2S_RULES are NOT implemented
 *    and must not be added: no player-level data is stored by the directory.
 *  - The result drops the server name; only counts, the password flag and the round trip leave
 *    this module.
 *  - Targets are addresses we learned from the Steam list; the caller (lib/directory-liveness.ts)
 *    refuses private/reserved/low ports. Nothing here scans address space.
 */

const HEADER = Buffer.from([0xff, 0xff, 0xff, 0xff]);
const INFO_PAYLOAD = Buffer.concat([Buffer.from([0x54]), Buffer.from("Source Engine Query\0", "latin1")]);

/** The A2S_INFO request; `challenge` (4 bytes from an 0x41 reply) is appended on the second step. */
export function buildInfoRequest(challenge?: Buffer): Buffer {
  if (challenge && challenge.length !== 4) throw new Error("A2S challenge must be 4 bytes");
  return Buffer.concat([HEADER, INFO_PAYLOAD, ...(challenge ? [challenge] : [])]);
}

