/**
 * The right liveness protocol per game family, for rows whose address we were given.
 *   a2s     Valve's A2S_INFO on the query port (every Source / Steam-networking dedicated server)
 *   slp     Minecraft Java Server List Ping (TCP)
 *   raknet  Minecraft Bedrock unconnected ping (UDP)
 *   listing the source's own heartbeat list is the evidence (TruckersMP, Vintage Story master)
 * null = no honest check exists: such a row is shown "seen on the list" with a short TTL, never "online".
 */
export function probeKindForGame(game: string): ProbeKind | null {
  if (game === "ets2" || game === "ats") return "listing";
  if (game === "vintagestory") return "listing";
  const p = QUERY_PROTOCOL[game as GameFamily];
  if (p === "mc-java") return "slp";
  if (p === "bedrock") return "raknet";
  if (p === "a2s") return "a2s";
  return null;
}
