/**
 * Vintage Story official master list: the same JSON the game client calls (servers opt in with
 * `AdvertiseServer` in their config). No key, no login, robots.txt is empty. The wiki documents the setting but
 * not the endpoint or any terms, so the source is AMBER: default OFF, and the owner records who asked the
 * developers / read their position before turning it on (docs/DIRECTORY-SOURCES.md).
 *
 * Verified live 2026-10-04: HTTP 200, ~4.5 MB, ~2,460 rows, `Cache-Control: max-age=300`, ETag. Fields:
 * serverName, serverIP "ip:port" | "host:port" | "[v6]:port", playstyle{id}, mods[], maxPlayers (string), players,
 * gameVersion, hasPassword, whitelisted, gameDescription. We poll once per 30 minutes with If-None-Match.
 *
 * Only servers anyone can join are listed: password-protected and whitelisted rows are dropped (about 70% of the
 * list), so the directory never advertises a server a visitor cannot enter. Mod ids and descriptions are not stored.
 */
export const VINTAGESTORY_URL = "https://masterserver.vintagestory.at/api/v1/servers/list";

export type VsRaw = {
  serverName?: unknown; serverIP?: unknown; playstyle?: { id?: unknown } | null; maxPlayers?: unknown; players?: unknown;
  gameVersion?: unknown; hasPassword?: unknown; whitelisted?: unknown;
};

const toInt = (v: unknown): number | null => {
  const n = typeof v === "string" ? Number(v.trim()) : typeof v === "number" ? v : NaN;
  return Number.isFinite(n) && n >= 0 && n <= 1_000_000 ? Math.floor(n) : null;
};

/** "ip:port" | "host.name:port". IPv6 literals are skipped (our probes and dedupe are IPv4/hostname only). */
export function parseVsAddress(raw: unknown): { host: string; ip: string | null; port: number } | null {
  const m = /^([A-Za-z0-9.-]{1,253}):(\d{1,5})$/.exec(String(raw ?? "").trim());
  if (!m) return null;
  const host = normalizeHost(m[1]);
  const port = Number(m[2]);
  if (!(port >= 1 && port <= 65535) || !isProbeablePort(port)) return null;
  if (isIpv4(host)) return isPublicIpv4(host) ? { host, ip: host, port } : null;
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(host) || /^(localhost|.*\.local|.*\.internal)$/.test(host)) return null;
  return { host, ip: null, port };
}

export function parseVsRow(r: VsRaw): ProviderCandidate | null {
  if (r.hasPassword !== false || r.whitelisted !== false) return null; // only open servers
  const addr = parseVsAddress(r.serverIP);
  if (!addr) return null;
  const name = cleanServerName(r.serverName);
  if (!name) return null;
  const max = toInt(r.maxPlayers), players = toInt(r.players);
  if (max !== null && players !== null && (max === 0 || players > max || max > 1000)) return null; // spoofed or implausible counts
  const style = cleanText(r.playstyle?.id, 24);
  const key = connKey("vintagestory", addr.host, addr.port);
  return {
    sourceKey: `${addr.host}:${addr.port}`, game: "vintagestory", name, host: addr.host, ip: addr.ip, port: addr.port, queryPort: null,
    map: null, players, maxPlayers: max, version: cleanText(r.gameVersion, 24), tags: style ? [style] : [], country: null,
    connKey: key, ipKey: addr.ip ? key : null, alive: true, // listed on the master = it heartbeated recently
  };
}

export function parseVsResponse(json: unknown): ProviderCandidate[] {
  const rows = (json as { data?: VsRaw[] } | null)?.data;
  if (!Array.isArray(rows)) return [];
  const seen = new Set<string>();
  const out: ProviderCandidate[] = [];
  for (const r of rows) {
    const c = parseVsRow(r);
    if (!c || seen.has(c.sourceKey)) continue;
    seen.add(c.sourceKey);
    out.push(c);
  }
  return out;
}

